-- StarterGui.ScreenGui.IMPORTANT WOOHOO.f3x.TextButton.LocalScript
local function C_15()
	local script = G2L["15"];
	local button = script.Parent
	local textbox = script.Parent.Parent:WaitForChild("nugget")

	button.MouseButton1Click:Connect(function()

		local assetId = textbox.Text
		if assetId == "" then return end

		local player = game.Players.LocalPlayer
		local char = player.Character or player.CharacterAdded:Wait()
		local tool

		for i,v in player:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end

		for i,v in game.ReplicatedStorage:GetDescendants() do
			if v.Name == "SyncAPI" then
				tool = v.Parent
			end
		end

		if not tool then return end

		local remote = tool.SyncAPI.ServerEndpoint

		function _(args)
			remote:InvokeServer(unpack(args))
		end

		function CreatePart(cf,parent)
			local args = {
				[1] = "CreatePart",
				[2] = "Normal",
				[3] = cf,
				[4] = parent
			}
			_(args)
		end

		function SetName(part, stringg)
			local args = {
				[1] = "SetName",
				[2] = { part },
				[3] = stringg
			}
			_(args)
		end

		function AddMesh(part)
			local args = {
				[1] = "CreateMeshes",
				[2] = {
					{
						Part = part
					}
				}
			}
			_(args)
		end

		function SetMesh(part,meshid)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					{
						Part = part,
						MeshId = "rbxassetid://"..meshid
					}
				}
			}
			_(args)
		end

		function SetTexture(part, texid)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					{
						Part = part,
						TextureId = "rbxassetid://"..texid
					}
				}
			}
			_(args)
		end

		function MeshResize(part,size)
			local args = {
				[1] = "SyncMesh",
				[2] = {
					{
						Part = part,
						Scale = size
					}
				}
			}
			_(args)
		end

		function SetLocked(part,boolean)
			local args = {
				[1] = "SetLocked",
				[2] = { part },
				[3] = boolean
			}
			_(args)
		end

		function Sky(id) 
			local e = char.HumanoidRootPart.CFrame.x
			local f = char.HumanoidRootPart.CFrame.y
			local g = char.HumanoidRootPart.CFrame.z

			CreatePart(
				CFrame.new(math.floor(e),math.floor(f),math.floor(g)) + Vector3.new(0,6,0),
				workspace
			)

			for i,v in game.Workspace:GetDescendants() do
				if v:IsA("BasePart") and v.CFrame.x == math.floor(e) and v.CFrame.z == math.floor(g) then

