			Enum.MeshType.Wedge
		}
		local function getBuildingTool(player)
			for _, container in ipairs({player.Character, player.Backpack}) do
				if container then
					for _, item in ipairs(container:GetChildren()) do
						if item:IsA("Tool") and item:FindFirstChild("SyncAPI") then
							return item
						end
					end
				end
			end
			return nil
		end
		local function removeMesh(part)
			for _, child in ipairs(part:GetChildren()) do
				if child:IsA("SpecialMesh") then
					local tool = getBuildingTool(player)
					if tool then
						tool.SyncAPI.ServerEndpoint:InvokeServer("Remove", {child})
					elseif not warned then
						warn("why 😢")
						warned = true
					end
				end
			end
		end
		local function isAccessoryPart(part)
			if part:IsA("Accessory") then
				return true
			end
			if part.Parent and part.Parent:IsA("Accessory") then
				return true
			end
			return false
		end
		local function applyMesh(part)
			if isAccessoryPart(part) then return end
			if not part:IsA("Part") then return end
			removeMesh(part)
			local randomMeshType = meshTypes[math.random(1, #meshTypes)]
			local tool = getBuildingTool(player)
			if tool then
				tool.SyncAPI.ServerEndpoint:InvokeServer("CreateMeshes", {{Part = part}})
				tool.SyncAPI.ServerEndpoint:InvokeServer("SyncMesh", {{MeshType = randomMeshType, Part = part}})
			elseif not warned then
				warn("why😢")
				warned = true
			end
		end
		local function randomizeCharacterMeshes(character)
			for _, obj in ipairs(character:GetDescendants()) do
				if obj:IsA("Part") and not isAccessoryPart(obj) then
					applyMesh(obj)
				end
			end
		end
		while true do
			if player.Character then
				randomizeCharacterMeshes(player.Character)
			end
			task.wait(0.5)
		end

	end)

end;
