			--workspace.Part
			local function CreateMesh(part,meshid)
				local args = {
					[1] = "CreateMeshes",
					[2] = {
						[1] = {
							["Part"] = part
						}
					}
				}

				Event:InvokeServer(unpack(args))
				local args = {
					[1] = "SyncMesh",
					[2] = {
						[1] = {
							["MeshType"] = Enum.MeshType.FileMesh,
							["Part"] = part
						}
					}
				}

				Event:InvokeServer(unpack(args))
				local args = {
					[1] = "SyncMesh",
					[2] = {
						[1] = {
							["Part"] = part,
							["MeshId"] = meshid
						}
					}
				}

				Event:InvokeServer(unpack(args))
			end

			local function CanCollide(part,cancollide)
				local args = {
					[1] = "SyncCollision",
					[2] = {
						[1] = {
							["Part"] = part,
							["CanCollide"] = cancollide
						}
					}
				}

				Event:InvokeServer(unpack(args))
			end

			local function Anchor(part,anchor)
				local args = {
					[1] = "SyncAnchor",
					[2] = {
						[1] = {
							["Part"] = part,
							["Anchored"] = anchor
						}
					}
				}

