-- StarterGui.ScreenGui.IMPORTANT WOOHOO.decal tab.LocalScript
local function C_a2()
	local script = G2L["a2"];
	local UserInputService = game:GetService("UserInputService")
	local RunService = game:GetService("RunService")

	local gui = script.Parent
	local DRAG_SPEED = 8

	local dragging = false
	local startPos
	local lastMousePos
	local lastGoalPos

	local function Lerp(a, b, m)
		return a + (b - a) * m
	end

	local function Update(dt)
		if not startPos then return end

		if not dragging and lastGoalPos then
			gui.Position = UDim2.new(
				startPos.X.Scale,
				Lerp(gui.Position.X.Offset, lastGoalPos.X.Offset, dt * DRAG_SPEED),
				startPos.Y.Scale,
				Lerp(gui.Position.Y.Offset, lastGoalPos.Y.Offset, dt * DRAG_SPEED)
			)
			return
		end

		if dragging then
			local delta = lastMousePos - UserInputService:GetMouseLocation()
			local xGoal = startPos.X.Offset - delta.X
			local yGoal = startPos.Y.Offset - delta.Y

			lastGoalPos = UDim2.new(startPos.X.Scale, xGoal, startPos.Y.Scale, yGoal)

			gui.Position = UDim2.new(
				startPos.X.Scale,
				Lerp(gui.Position.X.Offset, xGoal, dt * DRAG_SPEED),
				startPos.Y.Scale,
				Lerp(gui.Position.Y.Offset, yGoal, dt * DRAG_SPEED)
			)
		end
	end

	gui.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 
			or input.UserInputType == Enum.UserInputType.Touch then

			dragging = true
			startPos = gui.Position
			lastMousePos = UserInputService:GetMouseLocation()

			input.Changed:Connect(function()
				if input.UserInputState == Enum.UserInputState.End then
					dragging = false
				end
			end)
		end
	end)

	RunService.Heartbeat:Connect(Update)

end;
